                    <h2 id="endpoints-POSTapi-usuarios">Registro</h2>

<p>
</p>

<p>Crea un nuevo usuario en el sistema.</p>

<span id="example-requests-POSTapi-usuarios">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/usuarios" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"nombre_usuario\": \"consequatur\",
    \"nombre\": \"Juan Pérez\",
    \"apellido1\": \"consequatur\",
    \"password\": \"secret123\",
    \"email\": \"juan@correo.com\",
    \"telefono\": \"consequatur\",
    \"departamento\": \"consequatur\",
    \"estado\": \"consequatur\",
    \"roles\": []
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/usuarios"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "nombre_usuario": "consequatur",
    "nombre": "Juan Pérez",
    "apellido1": "consequatur",
    "password": "secret123",
    "email": "juan@correo.com",
    "telefono": "consequatur",
    "departamento": "consequatur",
    "estado": "consequatur",
    "roles": []
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

