                    <h2 id="endpoints-POSTapi-producto">Registra un nuevo producto en el sistema.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función actúa como el encargado de almacén que recibe un nuevo producto,
verifica que venga con toda su documentación (validación) y lo registra en el sistema
asignándole un lugar (estado).</p>

<span id="example-requests-POSTapi-producto">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/producto" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"nombre\": \"vmqeopfuudtdsufvyvddq\",
    \"descripcion\": \"consequatur\",
    \"marca\": \"mqeopfuudtdsufvyvddqa\",
    \"modelo\": \"mniihfqcoynlazghdtqtq\",
    \"precio_referencia_renta\": 80,
    \"sku\": \"bajwbpilpmufinllwloau\",
    \"numero_serie\": \"ydlsmsjuryvojcybzvrby\",
    \"categoria\": \"ickznkygloigmkwxphlva\",
    \"precio_alquiler_dia\": 87,
    \"precio_alquiler_semanal\": 34,
    \"precio_alquiler_mensual\": 60,
    \"precio_compra\": 8,
    \"valor_actual\": 48,
    \"fecha_compra\": \"2026-04-04T00:26:59\",
    \"condicion\": \"fbaqywuxhgjjmzuxjubqo\",
    \"ubicacion\": \"uzswiwxtrkimfcatbxspz\",
    \"notas\": \"consequatur\",
    \"estado\": \"mqeopfuudtdsufvyvddqa\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/producto"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "nombre": "vmqeopfuudtdsufvyvddq",
    "descripcion": "consequatur",
    "marca": "mqeopfuudtdsufvyvddqa",
    "modelo": "mniihfqcoynlazghdtqtq",
    "precio_referencia_renta": 80,
    "sku": "bajwbpilpmufinllwloau",
    "numero_serie": "ydlsmsjuryvojcybzvrby",
    "categoria": "ickznkygloigmkwxphlva",
    "precio_alquiler_dia": 87,
    "precio_alquiler_semanal": 34,
    "precio_alquiler_mensual": 60,
    "precio_compra": 8,
    "valor_actual": 48,
    "fecha_compra": "2026-04-04T00:26:59",
    "condicion": "fbaqywuxhgjjmzuxjubqo",
    "ubicacion": "uzswiwxtrkimfcatbxspz",
    "notas": "consequatur",
    "estado": "mqeopfuudtdsufvyvddqa"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

