                    <h2 id="endpoints-POSTapi-rol">Crea un nuevo rol de usuario.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como crear un nuevo puesto de trabajo en una empresa.
Se define el título (nombre), el código interno y las responsabilidades (descripción)
que tendrá quien ocupe ese puesto.</p>

<span id="example-requests-POSTapi-rol">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/rol" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"codigo\": \"consequatur\",
    \"nombre\": \"consequatur\",
    \"descripcion\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/rol"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "codigo": "consequatur",
    "nombre": "consequatur",
    "descripcion": "consequatur"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

<span id="example-responses-POSTapi-rol">
</span>
