<span id="example-requests-PATCHapi-cliente--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost/api/cliente/consequatur" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"nombre\": \"consequatur\",
    \"nombre2\": \"consequatur\",
    \"apellido1\": \"consequatur\",
    \"apellido2\": \"consequatur\",
    \"rfc\": \"consequatur\",
    \"telefono_principal\": \"consequatur\",
    \"correo_electronico\": \"consequatur\",
    \"tipo_cliente\": \"consequatur\",
    \"estado_cliente\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/cliente/consequatur"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "nombre": "consequatur",
    "nombre2": "consequatur",
    "apellido1": "consequatur",
    "apellido2": "consequatur",
    "rfc": "consequatur",
    "telefono_principal": "consequatur",
    "correo_electronico": "consequatur",
    "tipo_cliente": "consequatur",
    "estado_cliente": "consequatur"
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

