                    <h2 id="endpoints-POSTapi-cotizacion">Crea una nueva cotización y sus detalles.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como redactar un presupuesto formal.
Se suman los precios de todos los productos que el cliente quiere,
se aplican impuestos y descuentos, y se genera un documento con fecha de validez.</p>

<span id="example-requests-POSTapi-cotizacion">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/cotizacion" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"cliente_id\": \"consequatur\",
    \"solicitud_id\": \"consequatur\",
    \"fecha_cotizacion\": \"2026-04-04T00:26:59\",
    \"fecha_validez\": \"2026-04-04T00:26:59\",
    \"monto_total\": 11613.31890586,
    \"estado_cotizacion\": \"consequatur\",
    \"terminos_condiciones\": \"consequatur\",
    \"notas_internas\": \"consequatur\",
    \"detalles\": [
        {
            \"producto_id\": \"consequatur\",
            \"cantidad\": 45,
            \"precio_unitario\": 11613.31890586
        }
    ]
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/cotizacion"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "cliente_id": "consequatur",
    "solicitud_id": "consequatur",
    "fecha_cotizacion": "2026-04-04T00:26:59",
    "fecha_validez": "2026-04-04T00:26:59",
    "monto_total": 11613.31890586,
    "estado_cotizacion": "consequatur",
    "terminos_condiciones": "consequatur",
    "notas_internas": "consequatur",
    "detalles": [
        {
            "producto_id": "consequatur",
            "cantidad": 45,
            "precio_unitario": 11613.31890586
        }
    ]
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

<span id="example-responses-POSTapi-cotizacion">
</span>
<span id="execution-results-POSTapi-cotizacion" hidden>
    <blockquote>Received response<span
                id="execution-response-status-POSTapi-cotizacion"></span>:
    </blockquote>
    <pre class="json"><code id="execution-response-content-POSTapi-cotizacion"
