                    <h2 id="endpoints-POSTapi-detalleCotizacion">Agrega un item (detalle) a una cotización.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como agregar una línea específica al presupuesto:
'5 Sillas Modelo X a $10 cada una'.</p>

<span id="example-requests-POSTapi-detalleCotizacion">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/detalleCotizacion" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"cotizacion_id\": \"consequatur\",
    \"producto_id\": \"consequatur\",
    \"descripcion_item\": \"consequatur\",
    \"cantidad\": 11613.31890586,
    \"precio_unitario\": 11613.31890586,
    \"descuento_porcentaje\": 11613.31890586,
    \"impuestos_aplicables\": 11613.31890586,
    \"notas\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/detalleCotizacion"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "cotizacion_id": "consequatur",
    "producto_id": "consequatur",
    "descripcion_item": "consequatur",
    "cantidad": 11613.31890586,
    "precio_unitario": 11613.31890586,
    "descuento_porcentaje": 11613.31890586,
