                    <h2 id="endpoints-POSTapi-devolucion">Registra una nueva devolución de renta.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como el proceso de 'Check-out' en un hotel o alquiler de autos.
Se registra cuándo se devolvió el ítem, quién lo recibió y en qué estado se encuentra
(si hay daños o faltantes).</p>

<span id="example-requests-POSTapi-devolucion">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/devolucion" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"renta_id\": \"consequatur\",
    \"fecha_devolucion_programada\": \"2026-04-04T00:26:59\",
    \"fecha_devolucion_real\": \"2026-04-04T00:26:59\",
    \"estado_devolucion\": \"consequatur\",
    \"persona_recibe\": \"consequatur\",
    \"notas_generales\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/devolucion"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "renta_id": "consequatur",
    "fecha_devolucion_programada": "2026-04-04T00:26:59",
    "fecha_devolucion_real": "2026-04-04T00:26:59",
    "estado_devolucion": "consequatur",
    "persona_recibe": "consequatur",
    "notas_generales": "consequatur"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

