                    <h2 id="endpoints-POSTapi-direccion">Registra una nueva dirección en el sistema.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función actúa como el catastro municipal.
Registra una nueva ubicación física con todos sus detalles (calle, número, colonia)
para que el sistema sepa dónde entregar o recoger equipos.</p>

<span id="example-requests-POSTapi-direccion">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/direccion" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"calle\": \"consequatur\",
    \"numero_exterior\": \"consequatur\",
    \"numero_interior\": \"consequatur\",
    \"colonia\": \"consequatur\",
    \"ciudad\": \"consequatur\",
    \"estado_provincia\": \"consequatur\",
    \"codigo_postal\": \"consequatur\",
    \"pais\": \"consequatur\",
    \"referencias\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/direccion"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "calle": "consequatur",
    "numero_exterior": "consequatur",
    "numero_interior": "consequatur",
    "colonia": "consequatur",
    "ciudad": "consequatur",
    "estado_provincia": "consequatur",
    "codigo_postal": "consequatur",
    "pais": "consequatur",
    "referencias": "consequatur"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

