                    <h2 id="endpoints-POSTapi-mantenimiento">Registra un nuevo mantenimiento en el sistema.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Es como abrir una "Orden de Trabajo" en un taller mecánico.
Se anotan los datos del vehículo (item), qué se le va a hacer, quién lo hará y cuándo.</p>

<span id="example-requests-POSTapi-mantenimiento">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/mantenimiento" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"inventario_item_id\": \"consequatur\",
    \"fecha_inicio\": \"2026-04-04T00:27:00\",
    \"fecha_fin_prevista\": \"2107-05-03\",
    \"fecha_fin_real\": \"2026-04-04T00:27:00\",
    \"tipo_mantenimiento\": \"EMERGENCIA\",
    \"descripcion_problema\": \"mqeopfuudtdsufvyvddqa\",
    \"descripcion_trabajo_realizado\": \"mniihfqcoynlazghdtqtq\",
    \"costo_estimado\": 80,
    \"costo_real\": 6,
    \"estado_mantenimiento\": \"COMPLETADO\",
    \"responsable\": \"ajwbpilpmufinllwloauy\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/mantenimiento"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "inventario_item_id": "consequatur",
    "fecha_inicio": "2026-04-04T00:27:00",
    "fecha_fin_prevista": "2107-05-03",
    "fecha_fin_real": "2026-04-04T00:27:00",
    "tipo_mantenimiento": "EMERGENCIA",
    "descripcion_problema": "mqeopfuudtdsufvyvddqa",
    "descripcion_trabajo_realizado": "mniihfqcoynlazghdtqtq",
    "costo_estimado": 80,
    "costo_real": 6,
    "estado_mantenimiento": "COMPLETADO",
    "responsable": "ajwbpilpmufinllwloauy"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

