                    <h2 id="endpoints-DELETEapi-renta--id-">Elimina una renta y gestiona el estado de los equipos asociados.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como cancelar una reserva de hotel: no solo se borra la reserva,
sino que la habitación (equipo) se envía a limpieza (mantenimiento) para asegurar que
esté lista para el siguiente huésped.</p>

<span id="example-requests-DELETEapi-renta--id-">
