                    <h2 id="endpoints-POSTapi-solicitud">Crea una nueva solicitud de productos.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>ANALOGÍA: Esta función es como llenar un formulario de pedido en un restaurante:
el cliente (usuario) dice qué quiere comer (productos) y el mesero (sistema)
anota todo para pasarlo a la cocina.</p>

<span id="example-requests-POSTapi-solicitud">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/solicitud" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"cliente_id\": \"consequatur\",
    \"fecha_solicitud\": \"2026-04-04T00:27:00\",
    \"cantidad_solicitada\": 17,
    \"descripcion_necesidad\": \"consequatur\",
    \"estado_solicitud\": \"Atendida\",
    \"productos\": [
        {
            \"producto_id\": \"consequatur\",
            \"cantidad\": 17
        }
    ]
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/solicitud"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "cliente_id": "consequatur",
    "fecha_solicitud": "2026-04-04T00:27:00",
    "cantidad_solicitada": 17,
    "descripcion_necesidad": "consequatur",
    "estado_solicitud": "Atendida",
    "productos": [
        {
            "producto_id": "consequatur",
            "cantidad": 17
        }
    ]
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

